function decodeAbiString(hex) {
  const h = String(hex || '').replace(/^0x/, '');
  if (!h) return '';
  if (h.length === 64) return Buffer.from(h, 'hex').toString('utf8').replace(/\0/g, '').trim();
  const length = parseInt(h.slice(64, 128), 16);
  if (!Number.isFinite(length) || length <= 0) return '';
  return Buffer.from(h.slice(128, 128 + length * 2), 'hex').toString('utf8').trim();
}

function defaultFetchJson(url, options = {}) {
  return fetch(url, { headers: { 'User-Agent': 'TradAI payments' }, signal: AbortSignal.timeout(20000), ...options })
    .then(async (res) => { if (!res.ok) throw new Error(`HTTP ${res.status}`); return res.json(); });
}

async function defaultRpc(url, method, params) {
  const res = await fetch(url, {
    method: 'POST', headers: { 'Content-Type': 'application/json', 'User-Agent': 'TradAI payments' },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }), signal: AbortSignal.timeout(20000),
  });
  if (!res.ok) throw new Error(`RPC HTTP ${res.status}`);
  const json = await res.json();
  if (json.error) throw new Error(json.error.message || 'RPC error');
  return json.result;
}

async function defaultSolana(method, params) {
  const res = await fetch('https://api.mainnet-beta.solana.com', {
    method: 'POST', headers: { 'Content-Type': 'application/json', 'User-Agent': 'TradAI payments' },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }), signal: AbortSignal.timeout(20000),
  });
  if (!res.ok) throw new Error(`Solana HTTP ${res.status}`);
  const json = await res.json();
  if (json.error) throw new Error(json.error.message || 'Solana RPC error');
  return json.result;
}

